import { cn } from "@/lib/cn";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/modules/ui/components/table";
import {
  getBodyCellClassName,
  getFrameClassName,
  getHeaderCellClassName,
  getRowActivatorColumnId,
  isRowActivatable,
} from "./lib/column-classes";
import { SettingsTableSkeletonRows } from "./settings-table-skeleton";
import type { TSettingsTableProps } from "./types";

/**
 * The settings-page table: one frame, a tinted `h-12` header, divided rows.
 *
 * Columns are declared as data rather than JSX so that the header, the cells, the responsive hiding and
 * the loading skeleton all come from one source. Export the array from a `getXColumns(t, flags)` factory
 * and a `loading.tsx` can reuse it, which is what keeps a skeleton from drifting out of sync.
 *
 * Defaults to frameless, because the `<SettingsCard bodyVariant="flush">` it usually sits in already
 * provides the frame. Pass `frame="card"` when the table stands on its own.
 *
 * Deliberately has no `"use client"`: it holds no state, so a server component can render it too. Only
 * the interactive props (`onRowClick`, `getRowProps`) require a client caller.
 *
 * For anything the column API cannot express, drop down to the `Table` parts directly — they carry the
 * same visual defaults, so the escape hatch costs structural consistency but never visual consistency.
 */
export const SettingsTable = <TRow,>({
  columns,
  rows,
  getRowId,
  emptyMessage,
  frame = "none",
  isLoading = false,
  skeletonRows,
  isRowDisabled,
  footer,
  getRowProps,
  bodyProps,
  onRowClick,
  getRowLabel,
  isRowClickable,
  className,
  containerClassName,
  id,
  "aria-label": ariaLabel,
  "data-testid": dataTestId,
}: Readonly<TSettingsTableProps<TRow>>) => {
  const activatorColumnId = getRowActivatorColumnId(columns);

  const renderBody = () => {
    if (isLoading) {
      return <SettingsTableSkeletonRows columns={columns} rows={skeletonRows} />;
    }

    if (rows.length === 0) {
      return (
        <TableRow>
          <TableCell colSpan={columns.length} className="h-24 text-center text-sm text-slate-500">
            {emptyMessage}
          </TableCell>
        </TableRow>
      );
    }

    return rows.map((row, rowIndex) => {
      const isDisabled = isRowDisabled?.(row) ?? false;
      const isClickable = isRowActivatable({
        isDisabled,
        hasRowClick: Boolean(onRowClick),
        isRowClickable: isRowClickable?.(row),
      });

      return (
        <TableRow
          key={getRowId(row)}
          aria-disabled={isDisabled || undefined}
          className={cn(
            isClickable && "cursor-pointer hover:bg-slate-50",
            isDisabled && "pointer-events-none opacity-60"
          )}
          onClick={isClickable && onRowClick ? () => onRowClick(row) : undefined}
          {...getRowProps?.(row)}>
          {columns.map((column) => {
            const content = column.cell(row, rowIndex);

            return (
              <TableCell
                key={column.id}
                className={getBodyCellClassName(column)}
                onClick={column.stopRowClick ? (event) => event.stopPropagation() : undefined}>
                {isClickable && getRowLabel && column.id === activatorColumnId ? (
                  <button
                    type="button"
                    aria-label={getRowLabel(row)}
                    className="-m-1 flex w-full items-center rounded-sm p-1 text-left focus-visible:ring-2 focus-visible:ring-slate-400 focus-visible:outline-hidden">
                    {content}
                  </button>
                ) : (
                  content
                )}
              </TableCell>
            );
          })}
        </TableRow>
      );
    });
  };

  return (
    <div className={cn(getFrameClassName(frame), containerClassName)}>
      <Table id={id} aria-label={ariaLabel} data-testid={dataTestId} className={className}>
        <TableHeader>
          <TableRow className="bg-slate-100">
            {columns.map((column) => (
              <TableHead key={column.id} className={getHeaderCellClassName(column)}>
                {column.header}
                {column.header === null && column.srLabel ? (
                  <span className="sr-only">{column.srLabel}</span>
                ) : null}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody {...bodyProps}>{renderBody()}</TableBody>
      </Table>
      {footer}
    </div>
  );
};

export { SettingsTableSkeleton, SettingsTableSkeletonRows } from "./settings-table-skeleton";
export type {
  TSettingsTableAlign,
  TSettingsTableBreakpoint,
  TSettingsTableColumn,
  TSettingsTableFrame,
  TSettingsTableProps,
  TSettingsTableSkeletonProps,
} from "./types";

import type { ReactNode } from "react";

export type TSettingsTableAlign = "left" | "center" | "right";
export type TSettingsTableBreakpoint = "sm" | "md" | "lg";

/**
 * `none` — the table draws no frame, because a `<SettingsCard bodyVariant="flush">` already frames it.
 * `card` — the table draws its own frame, for use outside a settings card.
 */
export type TSettingsTableFrame = "none" | "card";

export type TSettingsTableColumn<TRow> = {
  /** Stable identifier, used as the React key for this column's header and every one of its cells. */
  id: string;
  /** Already-translated header label. `null` renders an empty header cell — pair it with `srLabel`. */
  header: ReactNode;
  cell: (row: TRow, index: number) => ReactNode;
  /**
   * Sets `text-align` on the header cell and every body cell in this column. Defaults to `left`.
   *
   * It moves **inline-level** content, which covers text, badges and `Button`/`Link` (both `inline-flex`).
   * It cannot move a block-level child, so a cell whose content is a wrapper `<div>` — or the skeleton's
   * placeholder bar — is unaffected by it. Declaring it alongside a flex wrapper is therefore inert; pick
   * one and let it be the only alignment source for the column.
   */
  align?: TSettingsTableAlign;
  /** Hides the column below this breakpoint. Applied to the header and body cells together. */
  hideBelow?: TSettingsTableBreakpoint;
  /**
   * Extra classes merged onto the `<th>`.
   *
   * This is where a column's **width** belongs (`w-[22%]`, `w-16`), because the header cell is what
   * sizes the whole column — putting a width on `cellClassName` only affects that one cell. Widths are
   * suggestions rather than commands: the table is `table-auto`, so a long value can still borrow space
   * from a short one, and when a `hideBelow` column drops out the remaining widths rescale.
   */
  headerClassName?: string;
  /**
   * Extra classes merged onto every `<td>` in this column, e.g. `font-medium text-slate-900`.
   *
   * **Do not change the cell's `display` here** — no `flex`, `grid` or `block`. These classes land on the
   * `<td>` itself, so overriding `display` stops it being a table-cell: the shared `align-middle` becomes
   * a no-op (`vertical-align` applies only to inline-level and table-cell boxes) and the browser wraps the
   * cell in an anonymous table-cell that defaults to baseline, so the content sits high in the row. To lay
   * cell content out, put the flex on a wrapper element **inside** `cell` instead. (`hideBelow` exists for
   * the same reason — it uses `table-cell`, not `block`.)
   */
  cellClassName?: string;
  /** Accessible name for a header cell whose `header` is `null` — typically an actions column. */
  srLabel?: string;
  /** Clicks inside this column do not activate the row. Use for action buttons and nested links. */
  stopRowClick?: boolean;
  /** Width of this column's skeleton bar. Defaults to `w-24`. */
  skeletonWidth?: `w-${string}`;
};

type SettingsTableBaseProps<TRow> = {
  columns: TSettingsTableColumn<TRow>[];
  rows: TRow[];
  getRowId: (row: TRow) => string;
  /** Already-translated. Rendered in a full-width cell when there are no rows. */
  emptyMessage: string;
  frame?: TSettingsTableFrame;
  isLoading?: boolean;
  skeletonRows?: number;
  /** Dims the row and blocks its interactions, e.g. while a sibling row's action is in flight. */
  isRowDisabled?: (row: TRow) => boolean;
  /** Non-row content rendered inside the frame, below the table — and outside its horizontal scroll. */
  footer?: ReactNode;
  /** Per-row DOM hooks. Prefer `data-testid` over `id`, which is not unique across rows. */
  getRowProps?: (row: TRow) => { id?: string; "data-testid"?: string };
  bodyProps?: { id?: string };
  id?: string;
  "aria-label"?: string;
  "data-testid"?: string;
  /** Classes for the `<table>` itself. */
  className?: string;
  /** Extra classes for the frame wrapper, e.g. a width constraint. Merged after `frame`. */
  containerClassName?: string;
};

/**
 * `getRowLabel` is required alongside `onRowClick`: the row's activator is a real `<button>`, and a
 * button built out of arbitrary cell content needs an accessible name.
 */
type SettingsTableClickProps<TRow> =
  | { onRowClick?: never; getRowLabel?: never; isRowClickable?: never }
  | {
      onRowClick: (row: TRow) => void;
      getRowLabel: (row: TRow) => string;
      isRowClickable?: (row: TRow) => boolean;
    };

export type TSettingsTableProps<TRow> = SettingsTableBaseProps<TRow> & SettingsTableClickProps<TRow>;

export type TSettingsTableSkeletonProps<TRow> = Pick<
  SettingsTableBaseProps<TRow>,
  "columns" | "frame" | "className" | "containerClassName"
> & { rows?: number };

"use client";

import { Trash2Icon } from "lucide-react";
import { useState } from "react";
import { useForm } from "react-hook-form";
import { toast } from "react-hot-toast";
import { useTranslation } from "react-i18next";
import { ApiKeyPermission } from "@formbricks/database/prisma-browser";
import { TOrganizationAccess } from "@formbricks/types/api-key";
import { TOrganizationWorkspace } from "@/modules/organization/settings/api-keys/types/api-keys";
import { Alert, AlertDescription, AlertTitle } from "@/modules/ui/components/alert";
import { Button } from "@/modules/ui/components/button";
import {
  Dialog,
  DialogBody,
  DialogContent,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/modules/ui/components/dialog";
import { Input } from "@/modules/ui/components/input";
import { InputCombobox, TComboboxOption } from "@/modules/ui/components/input-combo-box";
import { Label } from "@/modules/ui/components/label";
import { Switch } from "@/modules/ui/components/switch";

interface AddApiKeyModalProps {
  open: boolean;
  setOpen: (v: boolean) => void;
  onSubmit: (data: {
    label: string;
    workspacePermissions: Array<{
      permission: ApiKeyPermission;
      workspaceId: string;
    }>;
    organizationAccess: TOrganizationAccess;
  }) => Promise<void>;
  workspaces: TOrganizationWorkspace[];
  isCreatingAPIKey: boolean;
  isFormbricksCloud: boolean;
  /**
   * Whether the signed-in user clears USER_MANAGEMENT_MINIMUM_ROLE (ENG-3075). A key with
   * organization write access can manage the org's users, teams and workspace-team grants, so the
   * toggle is withheld rather than disabled when the floor is not cleared — `createApiKeyAction`
   * refuses the same request, and this keeps the form from offering it. Read access is not gated.
   */
  canGrantOrganizationWriteAccess: boolean;
}

interface PermissionRecord {
  workspaceId: string;
  permission: ApiKeyPermission;
  workspaceName: string;
}

export const AddApiKeyModal = ({
  open,
  setOpen,
  onSubmit,
  workspaces,
  isCreatingAPIKey,
  isFormbricksCloud,
  canGrantOrganizationWriteAccess,
}: Readonly<AddApiKeyModalProps>) => {
  const { t } = useTranslation();
  const { register, getValues, handleSubmit, reset, watch } = useForm<{ label: string }>();
  const apiKeyLabel = watch("label");
  const defaultOrganizationAccess: TOrganizationAccess = {
    accessControl: {
      read: false,
      write: false,
    },
  };

  const [selectedOrganizationAccess, setSelectedOrganizationAccess] =
    useState<TOrganizationAccess>(defaultOrganizationAccess);

  const getInitialPermissions = (): Record<string, PermissionRecord> => {
    if (workspaces.length > 0) {
      return {
        "permission-0": {
          workspaceId: workspaces[0].id,
          permission: ApiKeyPermission.read,
          workspaceName: workspaces[0].name,
        },
      };
    }
    return {};
  };

  // Initialize with one permission by default
  const [selectedPermissions, setSelectedPermissions] = useState<Record<string, PermissionRecord>>({});

  const workspaceOptions: TComboboxOption[] = workspaces.map((workspace) => ({
    value: workspace.id,
    label: workspace.name,
  }));

  const permissionOptions: TComboboxOption[] = [
    { value: ApiKeyPermission.read, label: t("workspace.api_keys.permission_read") },
    { value: ApiKeyPermission.write, label: t("workspace.api_keys.permission_write") },
    { value: ApiKeyPermission.manage, label: t("workspace.api_keys.permission_manage") },
  ];

  const removePermission = (index: number) => {
    const updatedPermissions = { ...selectedPermissions };
    delete updatedPermissions[`permission-${index}`];
    setSelectedPermissions(updatedPermissions);
  };

  const addPermission = () => {
    const newIndex = Object.keys(selectedPermissions).length;
    const initialPermission = getInitialPermissions()["permission-0"];
    if (initialPermission) {
      setSelectedPermissions({
        ...selectedPermissions,
        [`permission-${newIndex}`]: initialPermission,
      });
    }
  };

  const updatePermission = (key: string, field: string, value: string) => {
    setSelectedPermissions({
      ...selectedPermissions,
      [key]: {
        ...selectedPermissions[key],
        [field]: value,
      },
    });
  };

  // Update workspace selection
  const updateWorkspaceSelection = (key: string, workspaceId: string) => {
    const workspace = workspaces.find((p) => p.id === workspaceId);
    if (workspace) {
      setSelectedPermissions({
        ...selectedPermissions,
        [key]: {
          ...selectedPermissions[key],
          workspaceId,
          workspaceName: workspace.name,
        },
      });
    }
  };

  const checkForDuplicatePermissions = () => {
    const permissions = Object.values(selectedPermissions);
    const uniquePermissions = new Set(permissions.map((p) => p.workspaceId));
    return uniquePermissions.size !== permissions.length;
  };

  const submitAPIKey = async () => {
    const data = getValues();

    if (checkForDuplicatePermissions()) {
      toast.error(t("workspace.api_keys.duplicate_access"));
      return;
    }

    // Convert permissions to the format expected by the API
    const workspacePermissions = Object.values(selectedPermissions).map((permission) => ({
      permission: permission.permission,
      workspaceId: permission.workspaceId,
    }));

    await onSubmit({
      label: data.label,
      workspacePermissions,
      organizationAccess: selectedOrganizationAccess,
    });

    reset();
    setSelectedPermissions({});
    setSelectedOrganizationAccess(defaultOrganizationAccess);
  };

  const isSubmitDisabled = () => {
    // Check if label is empty or only whitespace
    if (!apiKeyLabel?.trim()) {
      return true;
    }

    // Check if at least one workspace permission is set or one organization access toggle is ON
    const hasWorkspaceAccess = Object.keys(selectedPermissions).length > 0;

    const hasOrganizationAccess = Object.values(selectedOrganizationAccess).some((accessGroup) =>
      Object.values(accessGroup).some((value) => value === true)
    );

    // Disable submit if no access rights are granted
    return !(hasWorkspaceAccess || hasOrganizationAccess);
  };

  const setSelectedOrganizationAccessValue = (key: string, accessType: string, value: boolean) => {
    setSelectedOrganizationAccess((prev) => ({
      ...prev,
      [key]: {
        ...prev[key],
        [accessType]: value,
      },
    }));
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle className="px-1">{t("workspace.api_keys.add_api_key")}</DialogTitle>
        </DialogHeader>
        <form onSubmit={handleSubmit(submitAPIKey)} className="contents">
          <DialogBody className="space-y-4 overflow-y-auto px-1 py-4">
            <div className="space-y-2">
              <Label>{t("workspace.api_keys.api_key_label")}</Label>
              <Input
                placeholder="e.g. GitHub, PostHog, Slack"
                {...register("label", { required: true, validate: (value) => value.trim() !== "" })}
              />
            </div>

            <div className="space-y-2">
              <Label>{t("workspace.api_keys.workspace_access")}</Label>
              <p className="text-sm text-slate-500">{t("workspace.api_keys.workspace_access_description")}</p>
              <div className="space-y-2">
                {Object.keys(selectedPermissions).length === 0 && (
                  <p className="text-sm text-slate-500">{t("workspace.api_keys.workspace_access_empty")}</p>
                )}
                {/* Permission rows */}
                {Object.keys(selectedPermissions).map((key) => {
                  const permissionIndex = parseInt(key.split("-")[1]);
                  const permission = selectedPermissions[key];
                  return (
                    <div key={key} className="flex items-center gap-2">
                      <div className="min-w-0 flex-1">
                        <InputCombobox
                          id={`workspace-select-${permissionIndex}`}
                          aria-label={t("common.workspace")}
                          options={workspaceOptions}
                          value={permission.workspaceId}
                          onChangeValue={(value) => {
                            if (typeof value === "string") updateWorkspaceSelection(key, value);
                          }}
                          showSearch
                          searchPlaceholder={t("common.search")}
                          comboboxClasses="flex-1 min-w-0 w-full"
                          emptyDropdownText={t("workspace.surveys.edit.no_option_found")}
                        />
                      </div>
                      <div className="min-w-0 flex-1">
                        <InputCombobox
                          id={`workspace-permission-select-${permissionIndex}`}
                          aria-label={t("workspace.api_keys.permissions")}
                          options={permissionOptions}
                          value={permission.permission}
                          onChangeValue={(value) => {
                            if (typeof value === "string") updatePermission(key, "permission", value);
                          }}
                          showSearch={false}
                          comboboxClasses="flex-1 min-w-0 w-full"
                        />
                      </div>

                      {/* Delete button */}
                      <button type="button" className="p-2" onClick={() => removePermission(permissionIndex)}>
                        <Trash2Icon className={"size-5 text-slate-500 hover:text-red-500"} />
                      </button>
                    </div>
                  );
                })}

                {/* Add permission button */}
                <Button
                  type="button"
                  variant="outline"
                  onClick={addPermission}
                  id="add_permission__button"
                  data-testid="add_permission__button__test">
                  <span className="mr-2">+</span> {t("workspace.settings.api_keys.add_permission")}
                </Button>
              </div>
            </div>

